import{_ as o,o as i,c as s,a2 as a}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Docker","description":"Docker reference documentation","frontmatter":{"title":"Docker","description":"Docker reference documentation"},"headers":[],"relativePath":"knowledge/docker.md","filePath":"knowledge/docker.md","lastUpdated":1784485118000}'),n={name:"knowledge/docker.md"};function t(r,e,c,l,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h1><h1 id="docker-knowledge-document" tabindex="-1">Docker Knowledge Document <a class="header-anchor" href="#docker-knowledge-document" aria-label="Permalink to &quot;Docker Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Docker enables consistent, reproducible environments by packaging applications and their dependencies into lightweight, portable containers. It eliminates &quot;it works on my machine&quot; problems and provides the foundation for modern CI/CD pipelines, microservices, and local development environments. Docker proficiency is essential for deploying, scaling, and debugging production applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="images-and-containers" tabindex="-1">Images and Containers <a class="header-anchor" href="#images-and-containers" aria-label="Permalink to &quot;Images and Containers&quot;">​</a></h3><p>An <strong>image</strong> is a read-only template with instructions for creating a container. A <strong>container</strong> is a running instance of an image. Images are built in layers, each representing a filesystem change. Layers are cached and reused across builds.</p><h3 id="dockerfile" tabindex="-1">Dockerfile <a class="header-anchor" href="#dockerfile" aria-label="Permalink to &quot;Dockerfile&quot;">​</a></h3><p>A Dockerfile defines the steps to build an image. Each instruction (<code>FROM</code>, <code>RUN</code>, <code>COPY</code>, <code>CMD</code>) creates a new layer. The order of instructions affects build cache efficiency and image size.</p><div class="language-dockerfile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:20-alpine </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm ci --only=production</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;server.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h3><p>Docker Compose defines multi-container applications using a YAML file. It manages networking, volumes, environment variables, and service dependencies. Compose v2 integrates directly with Docker CLI (<code>docker compose</code> up).</p><h3 id="volumes" tabindex="-1">Volumes <a class="header-anchor" href="#volumes" aria-label="Permalink to &quot;Volumes&quot;">​</a></h3><p>Volumes persist data beyond container lifecycle. Bind mounts map host directories to container paths (useful for development). Named volumes are managed by Docker and are portable across hosts.</p><h3 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h3><p>Docker creates virtual networks for container communication. The default bridge network allows containers to communicate by name. Host networking removes network isolation (useful for performance-sensitive applications).</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Use multi-stage builds</strong> — Separate build dependencies from runtime. Build in a full image, copy artifacts to a minimal alpine/distroless image. This can reduce image size by 80-90%.</p></li><li><p><strong>Order Dockerfile instructions by change frequency</strong> — Put rarely-changing instructions (base image, system dependencies) first. Put frequently-changing instructions (code copy) last. This maximizes cache hits.</p></li><li><p><strong>Use <code>.dockerignore</code> aggressively</strong> — Exclude <code>node_modules</code>, <code>.git</code>, <code>.env</code>, <code>dist</code>, test files, and documentation. Smaller build context = faster builds.</p></li><li><p><strong>Never run as root</strong> — Create a non-root user and switch to it before <code>CMD</code>. This prevents container escape vulnerabilities and follows security best practices.</p></li><li><p><strong>Pin base image versions</strong> — Use <code>node:20.11-alpine</code>, not <code>node:latest</code> or <code>node:20</code>. Patch versions may introduce breaking changes or security issues.</p></li><li><p><strong>Use <code>docker compose</code> for local development</strong> — Define all services (app, database, cache) in <code>docker-compose.yml</code>. Use <code>depends_on</code> with health checks for proper startup ordering.</p></li><li><p><strong>Implement health checks</strong> — Add <code>HEALTHCHECK</code> instructions to Dockerfiles. This enables Docker and orchestrators to detect and restart unhealthy containers automatically.</p></li><li><p><strong>Minimize layer count and size</strong> — Combine related <code>RUN</code> commands with <code>&amp;&amp;</code>. Clean up caches in the same layer (<code>apt-get clean &amp;&amp; rm -rf /var/lib/apt/lists/*</code>).</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Copying the entire filesystem without context</strong> — <code>COPY . .</code> copies everything. Use <code>.dockerignore</code> and be explicit with <code>COPY src/ ./src/</code> when possible.</p></li><li><p><strong>Running <code>apt-get upgrade</code> in images</strong> — This breaks reproducibility. Pin package versions or use a base image that already includes updates.</p></li><li><p><strong>Using <code>latest</code> tag in production</strong> — The <code>latest</code> tag is unpredictable. Always pin to specific versions for reproducible builds.</p></li><li><p><strong>Storing secrets in Docker images</strong> — Never <code>COPY .env</code> or hardcode credentials. Use runtime environment variables, Docker secrets, or a secrets manager.</p></li><li><p><strong>Using <code>docker exec</code> for debugging in production</strong> — Prefer logging, monitoring, and health checks. <code>exec</code> indicates a monitoring gap.</p></li><li><p><strong>Building images on production servers</strong> — Build in CI/CD and pull pre-built images. Production servers should only run containers, not build them.</p></li><li><p><strong>Ignoring container logs</strong> — Containers generate logs. Configure log rotation (<code>--log-opt max-size=10m --log-opt max-file=3</code>) to prevent disk exhaustion.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Not cleaning up after <code>apt-get install</code></strong> — Every <code>RUN</code> creates a layer. Un-cleaned caches persist in the image. Chain commands: <code>RUN apt-get update &amp;&amp; apt-get install -y pkg &amp;&amp; rm -rf /var/lib/apt/lists/*</code>.</p></li><li><p><strong>Using <code>CMD</code> with shell form</strong> — Use exec form: <code>CMD [&quot;node&quot;, &quot;server.js&quot;]</code>. Shell form wraps in <code>/bin/sh -c</code>, which prevents signal forwarding and PID 1 reaping.</p></li><li><p><strong>Forgetting <code>EXPOSE</code> documentation</strong> — <code>EXPOSE</code> doesn&#39;t publish ports; it documents which ports the container uses. Still important for clarity and tooling.</p></li><li><p><strong>Not using <code>.env</code> files with compose</strong> — Store non-sensitive configuration in <code>.env</code> files and reference with <code>env_file:</code> in compose. Keep secrets in a secrets manager.</p></li><li><p><strong>Mounting <code>node_modules</code> in development</strong> — Bind-mounting <code>node_modules</code> overwrites container&#39;s installed packages. Use named volumes for <code>node_modules</code> instead.</p></li><li><p><strong>Ignoring image size</strong> — Large images pull slowly and have larger attack surfaces. Use <code>alpine</code> or <code>distroless</code> base images. Check with <code>docker image ls</code> and <code>dive</code> tool.</p></li><li><p><strong>Not using <code>docker system prune</code> regularly</strong> — Dangling images, stopped containers, and unused networks accumulate. Run <code>docker system prune -a</code> periodically.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use Docker when:</strong> You need consistent environments across development, staging, and production. When deploying to Kubernetes, ECS, or any container orchestrator.</li><li><strong>Use Docker Compose when:</strong> You have multi-service local development (app + database + cache + worker). It simplifies service orchestration.</li><li><strong>Use multi-stage builds when:</strong> Your build process has heavy dependencies (compilers, build tools) that aren&#39;t needed at runtime.</li><li><strong>Use Docker in CI/CD when:</strong> You need reproducible build environments, isolated test databases, or consistent deployment artifacts.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Docker Official Docs: <a href="https://docs.docker.com" target="_blank" rel="noreferrer">https://docs.docker.com</a></li><li>Dockerfile Best Practices: <a href="https://docs.docker.com/develop/develop-images/dockerfile_best-practices/" target="_blank" rel="noreferrer">https://docs.docker.com/develop/develop-images/dockerfile_best-practices/</a></li><li>Docker Compose: <a href="https://docs.docker.com/compose/" target="_blank" rel="noreferrer">https://docs.docker.com/compose/</a></li><li>Dive (image inspector): <a href="https://github.com/wagoodman/dive" target="_blank" rel="noreferrer">https://github.com/wagoodman/dive</a></li><li>Hadolint (Dockerfile linter): <a href="https://github.com/hadolint/hadolint" target="_blank" rel="noreferrer">https://github.com/hadolint/hadolint</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>Use <code>docker compose -f docker-compose.dev.yml up</code> for development with hot-reload.</li><li><code>docker compose logs -f service_name</code> follows logs for a specific service.</li><li><code>docker volume ls</code> lists volumes; <code>docker volume inspect vol_name</code> shows mount paths.</li><li>For Next.js, mount the entire project directory for development but use multi-stage build for production.</li><li><code>docker buildx build --platform linux/amd64,linux/arm64 -t image:tag .</code> builds multi-architecture images.</li><li>Use <code>docker scan image:tag</code> (or <code>docker scout</code>) to check images for known vulnerabilities.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,30)])])}const m=o(n,[["render",t]]);export{g as __pageData,m as default};
